const form=document.getElementById("resumeForm"),printArea=document.getElementById("printArea"),printBtn=document.getElementById("printBtn"),printHint=document.getElementById("printHint");form&&form.addEventListener("submit",n=>{n.preventDefault();const e=new FormData(form),t=m=>(e.get(m)||"").trim(),p=t("name"),i=t("position"),d=t("phone"),r=t("email"),l=t("city"),o=t("about"),s=t("experience"),c=t("skills"),a=t("education");printArea.innerHTML=`
      <h1>${esc(p)}</h1>
      ${i?`<div class="sub">${esc(i)}</div>`:""}
      <div class="contacts">${[d,r,l].filter(Boolean).map(esc).join(" · ")}</div>
      ${o?`<h2>О себе</h2><p>${esc(o)}</p>`:""}
      ${s?`<h2>Опыт работы</h2><p>${esc(s)}</p>`:""}
      ${c?`<h2>Навыки</h2><p>${esc(c)}</p>`:""}
      ${a?`<h2>Образование</h2><p>${esc(a)}</p>`:""}
    `,printBtn&&(printBtn.disabled=!1),printHint&&(printHint.hidden=!1),printBtn.focus()}),printBtn&&printBtn.addEventListener("click",()=>{window.print()});function esc(n){return n.replace(/[&<>"']/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[e])}
